import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .u32 %r<24>;
    .reg .u64 %rd<32>;
    .reg .f32 %f<8>;
    .reg .pred %p<8>;
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ntid.x;
    mov.u32 %r6, %tid.x;
    mad.lo.s32 %r7, %r4, %r5, %r6;   // col
    mov.u32 %r8, %ctaid.y;
    mov.u32 %r9, %ntid.y;
    mov.u32 %r10, %tid.y;
    mad.lo.s32 %r11, %r8, %r9, %r10; // row
    setp.ge.s32 %p1, %r7, %r2;
    setp.ge.s32 %p2, %r11, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;
    mov.u32 %r13, %ctaid.z;    // split-K index
    mov.u32 %r14, %nctaid.z;   // number of K splits
    div.u32 %r15, %r3, %r14;   // chunk = K / splits (host guarantees exact division)
    mul.lo.s32 %r16, %r13, %r15; // k_start
    add.s32 %r17, %r16, %r15;    // k_end
    mov.f32 %f1, 0f00000000;
    mov.u32 %r12, %r16;
LOOP_START:
    setp.ge.s32 %p4, %r12, %r17;
    @%p4 bra LOOP_END;
    cvt.s64.s32 %rd4, %r11;
    cvt.s64.s32 %rd5, %r3;
    mul.lo.s64 %rd6, %rd4, %rd5;
    cvt.s64.s32 %rd7, %r12;
    add.s64 %rd8, %rd6, %rd7;
    shl.b64 %rd9, %rd8, 2;
    add.s64 %rd10, %rd1, %rd9;
    ld.global.f32 %f2, [%rd10];
    cvt.s64.s32 %rd11, %r12;
    cvt.s64.s32 %rd12, %r2;
    mul.lo.s64 %rd13, %rd11, %rd12;
    cvt.s64.s32 %rd14, %r7;
    add.s64 %rd15, %rd13, %rd14;
    shl.b64 %rd16, %rd15, 2;
    add.s64 %rd17, %rd2, %rd16;
    ld.global.f32 %f3, [%rd17];
    fma.rn.f32 %f1, %f2, %f3, %f1;
    add.s32 %r12, %r12, 1;
    bra LOOP_START;
LOOP_END:
    cvt.s64.s32 %rd18, %r11;
    cvt.s64.s32 %rd19, %r2;
    mul.lo.s64 %rd20, %rd18, %rd19;
    cvt.s64.s32 %rd21, %r7;
    add.s64 %rd22, %rd20, %rd21;
    shl.b64 %rd23, %rd22, 2;
    add.s64 %rd24, %rd3, %rd23;
    atom.global.add.f32 %f4, [%rd24], %f1;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented via a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"

        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"

        splits = 1
        max_splits = 64
        while splits < max_splits and K % (splits * 2) == 0:
            splits *= 2
        C = torch.zeros((M, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid = ((N + block[0] - 1) // block[0], (M + block[1] - 1) // block[1], splits)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

